from __future__ import annotations

def calculate_sums(a, b, c, d):
    sum1 = a ** 2 + b ** 2
    sum2 = c ** 2 + d ** 2
    product = sum1 * sum2
    results = []
    for e in range(int(product ** 0.5) + 1):
        f_squared = product - e ** 2
        f = int(f_squared ** 0.5)
        if f * f == f_squared:
            results.append([min(e, f), max(e, f)])
    results.sort()
    return results

def find_squares(n):
    solutions = []
    for e in range(n + 1):
        f = n - e
        if e * e + f * f == n:
            solutions.append([min(e, f), max(e, f)])
    return sorted(solutions)

def prod2sum(a, b, c, d):
    sum1 = a ** 2 + b ** 2
    sum2 = c ** 2 + d ** 2
    n = sum1 * sum2
    squares = find_squares(n)
    result = []
    for e, f in squares:
        if e >= f:
            result.append([f, e])
        else:
            result.append([e, f])
    result.sort()
    return result

